    fun operations(name: String): List<SymmetryOperation> {
        val number = find(name)?.number ?: return listOf(SymmetryOperation.IDENTITY)
        return operationsTable[number]?.map { SymmetryOperation.parse(it) }
            ?: listOf(SymmetryOperation.IDENTITY)
    }

    /** Space-group numbers that use the rhombohedral (R) lattice setting. */
    val RHOMBOHEDRAL_GROUPS: Set<Int> = setOf(146, 148, 155, 160, 161, 166, 167)

    /** True when [name] resolves to an R-lattice trigonal space group. */
    fun isRhombohedral(name: String): Boolean = find(name)?.number in RHOMBOHEDRAL_GROUPS

    private fun crystalSystem(n: Int) = when (n) {
        1, 2 -> "Triclinic"
        in 3..15 -> "Monoclinic"
        in 16..74 -> "Orthorhombic"
        in 75..142 -> "Tetragonal"
        in 143..167 -> "Trigonal"
        in 168..194 -> "Hexagonal"
        else -> "Cubic"
    }

    private fun pointGroup(n: Int) = when (n) {
        1 -> "1"; 2 -> "-1"; in 3..5 -> "2"; in 6..9 -> "m"; in 10..15 -> "2/m"
        in 16..24 -> "222"; in 25..46 -> "mm2"; in 47..74 -> "mmm"
        in 75..80 -> "4"; in 81..82 -> "-4"; in 83..88 -> "4/m"; in 89..98 -> "422"
        in 99..110 -> "4mm"; in 111..122 -> "-42m"; in 123..142 -> "4/mmm"
        in 143..146 -> "3"; in 147..148 -> "-3"; in 149..155 -> "32"; in 156..161 -> "3m"
        in 162..167 -> "-3m"; in 168..173 -> "6"; 174 -> "-6"; in 175..176 -> "6/m"
        in 177..182 -> "622"; in 183..186 -> "6mm"; in 187..190 -> "-6m2"; in 191..194 -> "6/mmm"
        in 195..199 -> "23"; in 200..206 -> "m-3"; in 207..214 -> "432"; in 215..220 -> "-43m"
        else -> "m-3m"
    }
}